/**
 * This test case verifies CBRD-27245: Improve lexer input handling for UTF-8 statements
 *
 * Coverage: string literals padded so a quote/escape construct straddles the
 * scanner's bulk-copy chunk boundary (~4KB/8KB/16KB), with backslash escapes
 * enabled so the escape-pair state machine is actually exercised.
 * 1-3   - no padding (control)
 * 4-12  - padding swept near a 4KB boundary (offsets -6, -2, -1 bytes)
 * 13-15 - padding at a tight offset near an 8KB boundary
 * 16-18 - padding at a tight offset near a 16KB boundary
 */

SET SYSTEM PARAMETERS 'no_backslash_escapes=no';

evaluate 'Case 1: pad=0 bytes, escaped quote pair (\') straddling the boundary';
SELECT 'a\'b', 'END1' FROM db_root;

evaluate 'Case 2: pad=0 bytes, escaped backslash pair (\\) straddling the boundary, closing quote right after';
SELECT 'a\\', 'END2' FROM db_root;

evaluate 'Case 3: pad=0 bytes, backslash-n escape (\\n) straddling the boundary';
SELECT '\n', 'END3' FROM db_root;

evaluate 'Case 4: pad=4090 bytes, escaped quote pair (\') straddling the boundary';
SELECT '\'b', 'END1' FROM db_root;

evaluate 'Case 5: pad=4090 bytes, escaped backslash pair (\\) straddling the boundary, closing quote right after';
SELECT '\\', 'END2' FROM db_root;

evaluate 'Case 6: pad=4090 bytes, backslash-n escape (\\n) straddling the boundary';
SELECT '\n', 'END3' FROM db_root;

evaluate 'Case 7: pad=4094 bytes, escaped quote pair (\') straddling the boundary';
SELECT '\'b', 'END1' FROM db_root;

evaluate 'Case 8: pad=4094 bytes, escaped backslash pair (\\) straddling the boundary, closing quote right after';
SELECT '\\', 'END2' FROM db_root;

evaluate 'Case 9: pad=4094 bytes, backslash-n escape (\\n) straddling the boundary';
SELECT '\n', 'END3' FROM db_root;

evaluate 'Case 10: pad=4095 bytes, escaped quote pair (\') straddling the boundary';
SELECT '\'b', 'END1' FROM db_root;

evaluate 'Case 11: pad=4095 bytes, escaped backslash pair (\\) straddling the boundary, closing quote right after';
SELECT '\\', 'END2' FROM db_root;

evaluate 'Case 12: pad=4095 bytes, backslash-n escape (\\n) straddling the boundary';
SELECT '\n', 'END3' FROM db_root;

evaluate 'Case 13: pad=8191 bytes, escaped quote pair (\') straddling the boundary';
SELECT '\'b', 'END1' FROM db_root;

evaluate 'Case 14: pad=8191 bytes, escaped backslash pair (\\) straddling the boundary, closing quote right after';
SELECT '\\', 'END2' FROM db_root;

evaluate 'Case 15: pad=8191 bytes, backslash-n escape (\\n) straddling the boundary';
SELECT '\n', 'END3' FROM db_root;

evaluate 'Case 16: pad=16383 bytes, escaped quote pair (\') straddling the boundary';
SELECT '\'b', 'END1' FROM db_root;

evaluate 'Case 17: pad=16383 bytes, escaped backslash pair (\\) straddling the boundary, closing quote right after';
SELECT '\\', 'END2' FROM db_root;

evaluate 'Case 18: pad=16383 bytes, backslash-n escape (\\n) straddling the boundary';
SELECT '\n', 'END3' FROM db_root;

SET SYSTEM PARAMETERS 'no_backslash_escapes=yes';
